import{_ as o,o as t,c as d,ae as c}from"./chunks/framework.YL6nI5ZP.js";const s="/docs/assets/architecture.DfaALXEV.png",g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/01-architecture.md","filePath":"explanation/01-architecture.md"}'),a={name:"explanation/01-architecture.md"};function n(r,e,i,l,p,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>The big picture: a client-side-only web application for 2D hydraulic modeling, where everything — the editor, the mesher, and the SWMM hydraulics engine — runs in the browser.</p><h2 id="client-side-only-design" tabindex="-1">Client-side-only design <a class="header-anchor" href="#client-side-only-design" aria-label="Permalink to &quot;Client-side-only design&quot;">​</a></h2><p>Local SWMM is a <strong>client-side-only web application</strong> for 2D hydraulic modeling and simulation of stormwater and wastewater networks. Everything — the editor, the mesher, and the SWMM hydraulics engine — runs in the browser. The simulation engine is the HydroCouple <strong>OpenSWMM</strong> engine compiled to <strong>WebAssembly</strong> with Emscripten.</p><p>The experimental branch adds the 2D surface-routing module (mesh generation, 1D↔2D coupling, WebGPU GPU marcher) on top of the 1D network editor.</p><h2 id="key-properties" tabindex="-1">Key properties <a class="header-anchor" href="#key-properties" aria-label="Permalink to &quot;Key properties&quot;">​</a></h2><ul><li><strong>No backend.</strong> The only server is a trivial static-file + health endpoint server (<code>server.py</code>). No database, no build step for the UI, no bundler.</li><li><strong>No UI framework.</strong> The frontend is ~15,000 lines of dependency-free JavaScript (classic scripts + IIFEs) using Mapbox GL JS as the only heavyweight runtime library.</li><li><strong>WASM-embedded hydraulics.</strong> The OpenSWMM 6.0.0 engine is cross-compiled for <code>wasm32-emscripten</code> with vcpkg-managed C++ dependencies (Eigen, HDF5, nlohmann-json, SUNDIALS).</li><li><strong>Two simulation backends.</strong> A WASM engine path (1D + 1D/2D coupled) and an <strong>experimental WebGPU</strong> backend that re-implements the 2D explicit local-inertial solver as WGSL compute kernels and runs it in parallel to the WASM engine.</li><li><strong>Two mesh generators.</strong> A legacy <code>poly2tri</code>-based generator and the production <strong>Shewchuk Triangle WASM</strong> (npm <code>triangle-wasm</code>) pipeline.</li></ul><h2 id="architecture-at-a-glance" tabindex="-1">Architecture at a glance <a class="header-anchor" href="#architecture-at-a-glance" aria-label="Permalink to &quot;Architecture at a glance&quot;">​</a></h2><p><img src="'+s+`" alt="LocalSWMM architecture"></p><p><strong>Data flow (simulation):</strong> model (<code>Net</code>) → <code>inpExporter.generateInp()</code> → optional 2D section injection (<code>Mesh2DInp.buildInput</code>) → <code>.inp</code> string → Worker → <code>FS.writeFile(&#39;/in.inp&#39;)</code> → <code>swmm_engine_open/initialize/start</code> → <code>stride()</code> loop → <code>.rpt</code> + <code>.out</code> read back → <code>swmmOutParser</code> → <code>results.js</code> rendering (tables, map colors, time slider, profile/chart plots).</p><h2 id="module-system-and-globals" tabindex="-1">Module system and globals <a class="header-anchor" href="#module-system-and-globals" aria-label="Permalink to &quot;Module system and globals&quot;">​</a></h2><p>There are <strong>no ES modules, no bundler, no <code>import</code>/<code>export</code></strong>. Every file is a classic script wrapped in an IIFE. Modules communicate exclusively through globals attached to <code>window</code>. <strong>Script order in <code>index.html</code> is the dependency contract</strong> (<code>index.html:779-810</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config.js → mapbox/proj4/shp/dxf/poly2tri/geotiff (CDN)</span></span>
<span class="line"><span>→ inpParser → inpExporter → network → swmmOutParser → street_view_overlay</span></span>
<span class="line"><span>→ swmm6wasm → results → importers → app → tools → profile → plot</span></span>
<span class="line"><span>→ vendor/triangle → mesh2dProj → mesh2dPslg → mesh2dTerrain → mesh2dTriangle</span></span>
<span class="line"><span>→ mesh2dCoupling → mesh2dExport → mesh2dRender → meshGlLayer → mesh2d</span></span>
<span class="line"><span>→ mesh2dInp → mesh2dDialog → layerTree → landcover → curves → lid → quality</span></span>
<span class="line"><span>→ aquifer → snowpack → ui          (ui.js LAST — it wires every button)</span></span></code></pre></div><p>The principal global singletons:</p><table tabindex="0"><thead><tr><th>Global</th><th>Owner of</th><th>Defined at</th></tr></thead><tbody><tr><td><code>window.map</code></td><td>Mapbox GL <code>Map</code> instance</td><td><code>app.js:38</code></td></tr><tr><td><code>window.App</code></td><td>UI/app state (<code>currentStyle</code>, visibility flags, <code>selection</code> Set, <code>lastRunReport</code>, <code>results2D</code>, <code>outData</code>, …)</td><td><code>app.js:44-58</code></td></tr><tr><td><code>window.Net</code></td><td><code>Network</code> class instance — <strong>single source of truth</strong> for all model data + undo/redo + autosave</td><td><code>network.js:942</code></td></tr><tr><td><code>window.Tools</code></td><td>Tool state machine (selection, drawing, hit-testing, drag)</td><td><code>tools.js:291</code></td></tr><tr><td><code>window.LayerTree</code></td><td>2D mesh layer visibility/opacity</td><td><code>layerTree.js:38</code></td></tr><tr><td><code>window.ResultStyling</code></td><td>Simulation result coloring engine</td><td><code>results.js:547</code></td></tr><tr><td><code>window.AnimationUI</code></td><td>Time-slider play/pause</td><td><code>ui.js:1086</code></td></tr><tr><td><code>window.CONFIG</code></td><td>API keys</td><td><code>config.js</code></td></tr><tr><td><code>window.inpParser</code> / <code>window.inpExporter</code></td><td>INP parse / serialize</td><td><code>inpParser.js:555</code>, <code>inpExporter.js</code></td></tr><tr><td><code>window.SWMMOutParser</code></td><td><code>.out</code> binary parser</td><td><code>swmmOutParser.js</code></td></tr><tr><td><code>window.Mesh2D…</code> / <code>window.TriangleWASM</code> / <code>window.Mesh2DLayers</code> / <code>window.Mesh2DGL</code></td><td>2D subsystem</td><td>see the 2D mesh &amp; WebGPU subsystem</td></tr><tr><td>Module editors (lazy)</td><td><code>CurveEditor</code>, <code>LIDControls</code>, <code>QualityEditor</code>, <code>AquiferEditor</code>, <code>SnowpackEditor</code>, <code>TimeSeriesPlot</code>, <code>ProfilePlot</code>, <code>StreetViewOverlay</code>, <code>Importers</code></td><td>—</td></tr></tbody></table><p>Consequences of this design:</p><ul><li><strong>State is shared by convention.</strong> <code>tools.js:8-9</code> and <code>ui.js:7-8</code> capture <code>window.map</code>/<code>window.App</code> at load time, so <code>ui.js</code> must load after <code>app.js</code>.</li><li><strong>Adding a module</strong> means adding a <code>&lt;script&gt;</code> tag in the right position in <code>index.html</code> and exposing globals; there is no import graph the tooling can validate.</li><li><strong>Rendering is two-track:</strong> <code>Net</code> owns geometry + undo + persistence (data); <code>App</code> + Mapbox own view state. Mapbox <strong>feature-state</strong> (<code>selected</code>, <code>hovered</code>, <code>resultColor</code>) is the bridge between them (<code>app.js:320-325</code>).</li></ul><h2 id="ui-shell-—-index-html" tabindex="-1">UI shell — <code>index.html</code> <a class="header-anchor" href="#ui-shell-—-index-html" aria-label="Permalink to &quot;UI shell — \`index.html\`&quot;">​</a></h2><p>The whole app is a CSS grid <code>#app-grid</code> (<code>styles.css:59-73</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grid-template-areas:</span></span>
<span class="line"><span>  &quot;toolbar toolbar toolbar&quot;</span></span>
<span class="line"><span>  &quot;palette map     panel&quot;</span></span>
<span class="line"><span>  &quot;status  status  status&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Container</th><th>ID</th><th>Contents</th></tr></thead><tbody><tr><td>Toolbar</td><td><code>#toolbar</code></td><td>Undo/Redo · Save/Load(dropdown)/Export-INP · Options · Mesh2D · TS-plot · <strong>Run</strong> · Clear · Data-menu (Curves/LID/Quality/Aquifer/Snowpack/2D Mesh)</td></tr><tr><td>Left palette</td><td><code>#tool-palette</code></td><td><code>[select] [delete]</code> + Node tools (junction, outfall, storage, divider) + Link tools (conduit, pump, weir, orifice) + Area tools (subcatchment, raingage)</td></tr><tr><td>Map area</td><td><code>#map-container</code></td><td><code>#map</code>, OSM search, map-settings card (basemap / layer toggles / units / DEM source / Sample-DEM-all), layer-tree card, Street View pegman, time-slider panel, profile modal, TS modals</td></tr><tr><td>Right panel</td><td><code>#panel-right</code></td><td>Resizable; tabs <strong>Properties / Results / Report</strong> (<code>#tab-props</code>, <code>#tab-results</code>, <code>#tab-report</code>)</td></tr><tr><td>Status bar</td><td><code>#statusbar</code></td><td><code>#sb-tool</code>, <code>#sb-nodes</code>, <code>#sb-links</code>, <code>#sb-subcatchments</code>, <code>#sb-gages</code>, <code>#sb-coords</code></td></tr><tr><td>Modals</td><td><code>.modal-overlay</code>+<code>.modal-box</code></td><td>Options, Projection, Import-As, 2D-Mesh (3 tabs), Run-Status (+minimized badge)</td></tr></tbody></table><h2 id="ui-framework" tabindex="-1">UI framework <a class="header-anchor" href="#ui-framework" aria-label="Permalink to &quot;UI framework&quot;">​</a></h2><p><strong>Hand-rolled, dependency-free.</strong> Dynamic content is DOM-string + <code>innerHTML</code> (e.g. the properties panel <code>renderPropsPanel</code>, <code>ui.js:842</code>); all wiring is <code>addEventListener</code>. Recurring component classes live in <code>styles.css</code>:</p><ul><li><code>.tb-btn</code>, <code>.tb-btn-run</code>, <code>.tb-icon-btn</code>, <code>.tb-dropdown</code>(+<code>.open</code>), <code>.tb-pill</code>(+<code>.active</code>)</li><li><code>.tool-btn</code>(+<code>.active</code>, <code>.tool-btn-danger</code>), <code>.tool-divider</code>, <code>.tool-group-label</code></li><li><code>.side-panel</code>, <code>.panel-tabs</code>, <code>.panel-tab</code>(+<code>.active</code>), <code>.tab-badge</code></li><li><code>.modal-overlay</code>, <code>.modal-box</code>, <code>.modal-actions</code></li><li><code>.prop-section-title</code>, <code>.prop-row</code>, <code>.prop-actions</code></li></ul><p><strong>Theming</strong> uses CSS variables (<code>styles.css:6-29</code>): <code>--accent</code>, <code>--danger</code>, <code>--bg-panel</code>, layout vars <code>--toolbar-h:44px</code>, <code>--statusbar-h:26px</code>, <code>--panel-w:280px</code>, <code>--palette-w:46px</code>. <code>--panel-w</code> is updated at runtime during resize (<code>ui.js:236</code>).</p><p><strong>No i18n.</strong> All strings are hardcoded English. The only &quot;localization&quot; is unit formatting via <code>const U = (si, us) =&gt; Net.units === &#39;US&#39; ? us : si;</code> (<code>ui.js:564</code>) used by the schema-driven property forms (<code>FIELD_DEFS</code>, <code>ui.js:570-736</code>).</p><h2 id="tool-system-—-tools-js" tabindex="-1">Tool system — <code>tools.js</code> <a class="header-anchor" href="#tool-system-—-tools-js" aria-label="Permalink to &quot;Tool system — \`tools.js\`&quot;">​</a></h2><p>A single hand-rolled state machine (<code>window.Tools</code>):</p><ul><li>Tool registry maps palette <code>data-tool</code> names to types: <code>NODE_TOOL_TYPES</code> (<code>junction→JUNCTION</code>, <code>outfall→OUTFALL</code>, <code>storage→STORAGE</code>, <code>divider→DIVIDER</code>, <code>raingage→RAINGAGE</code> — <code>tools.js:11-17</code>) and <code>LINK_TOOL_TYPES</code> (<code>conduit</code>, <code>pump</code>, <code>orifice</code>, <code>weir</code>, <code>outlet</code> — <code>tools.js:18-24</code>), plus special modes <code>select</code>, <code>subcatchment</code>, <code>delete</code>.</li><li><strong><code>Tools.setTool(name)</code></strong> (<code>tools.js:145-164</code>) cancels drawing, toggles palette highlight, updates <code>#sb-tool</code>, switches the map cursor, and disables <code>map.doubleClickZoom</code> in subcatchment mode.</li><li><strong>Drawing state:</strong> <code>linkFrom</code> (first endpoint), <code>linkVertices[]</code>, <code>polyVertices[]</code>, <code>dragging</code>.</li><li><strong>Hit-testing:</strong> <code>featureAt(point)</code> ranks nodes &gt; links &gt; subcatchments &gt; 2D mesh in a 12 px box (<code>tools.js:216-226</code>); <code>snapNodeAt</code> uses a 24 px box over <code>swmm-nodes-layer</code>, skipping rain gages for hydraulic ops (<code>tools.js:228-239</code>).</li><li><strong>All map interactions dispatch through one <code>map.on(&#39;click&#39;)</code> handler</strong> (<code>tools.js:295-363</code>) that switches on <code>Tools.active</code>: node placement, link drawing (first click must land on a node; subsequent clicks snap), subcatchment vertex push, delete, select. <code>dblclick</code> finishes a subcatchment (<code>tools.js:365-371</code>). <code>mousemove</code> updates the ghost draft and the hover popup (<code>tools.js:375-423</code>). <code>mousedown</code> drives node dragging (<code>tools.js:426-470</code>), coalesced into a single undo step via <code>Net.commitMove()</code> on mouseup.</li><li><strong>Keyboard</strong> (<code>tools.js:473-505</code>): <code>Esc</code> cancels/clears, <code>Ctrl+Z</code>/<code>Ctrl+Y</code>/<code>Ctrl+Shift+Z</code> undo-redo, <code>Ctrl+A</code> select all, <code>Del</code>/<code>Backspace</code> delete, <code>Enter</code> finishes a subcatchment.</li></ul><blockquote><p>Adding a new tool requires: an entry in <code>NODE_TOOL_TYPES</code>/<code>LINK_TOOL_TYPES</code>, a branch in the <code>click</code> handler, and a palette button.</p></blockquote><h2 id="state-persistence" tabindex="-1">State persistence <a class="header-anchor" href="#state-persistence" aria-label="Permalink to &quot;State persistence&quot;">​</a></h2><ul><li><strong>Autosave:</strong> every <code>Net.emit()</code> triggers <code>scheduleAutosave()</code> (<code>network.js:168</code>), a 2 s debounce that writes <code>JSON.stringify(serialize())</code> to <strong>localStorage</strong> key <code>openswmm3d.project</code> (<code>network.js:677-701</code>). If localStorage throws (quota), it falls back to <strong>IndexedDB</strong> (DB <code>openswmm3d</code>, store <code>kv</code>) (<code>network.js:703-718</code>). Restore prefers localStorage, then IndexedDB (<code>network.js:734-737</code>), gated on ≥1 node/link.</li><li><strong>Save / Load:</strong> <code>Net.downloadProject()</code> produces a pretty-printed <code>*.oswmm.json</code> (<code>network.js:774-781</code>); load goes through <code>Net.loadState(data, true)</code> (<code>network.js:490-520</code>). JSON and GeoJSON files are both accepted (GeoJSON routes to the import/projection dialogs).</li><li><strong>Panel geometry</strong> is also persisted: right-panel width in <code>localStorage[&#39;panel-w&#39;]</code>, layer-tree state in <code>localStorage[&#39;swmm-2d-layer-tree&#39;]</code> (<code>layerTree.js:8-9</code>).</li></ul>`,32)])])}const m=o(a,[["render",n]]);export{g as __pageData,m as default};
